/// Named CSR registers for common addresses.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CsrId(pub u16);

impl CsrId {
    pub const MSTATUS: Self = Self(0x300);
    pub const MISA: Self = Self(0x301);
    pub const MEPC: Self = Self(0x341);
    pub const MCAUSE: Self = Self(0x342);
    pub const MTVAL: Self = Self(0x343);
    pub const SSTATUS: Self = Self(0x100);
    pub const SEPC: Self = Self(0x141);
    pub const CYCLE: Self = Self(0xC00);
    pub const TIME: Self = Self(0xC01);
    pub const INSTRET: Self = Self(0xC02);
    pub const VSTART: Self = Self(0x008);
    pub const VXSAT: Self = Self(0x009);
    pub const VXRM: Self = Self(0x00A);
    pub const VCSR: Self = Self(0x00F);
    pub const VL: Self = Self(0xC20);
    pub const VTYPE: Self = Self(0xC21);
    pub const VLENB: Self = Self(0xC22);

    /// Return a human-readable name if the CSR is a well-known register.
    #[must_use] 
    pub fn name(&self) -> String {
        match self.0 {
            0x300 => "mstatus".to_owned(),
            0x301 => "misa".to_owned(),
            0x341 => "mepc".to_owned(),
            0x342 => "mcause".to_owned(),
            0x343 => "mtval".to_owned(),
            0x100 => "sstatus".to_owned(),
            0x141 => "sepc".to_owned(),
            0xC00 => "cycle".to_owned(),
            0xC01 => "time".to_owned(),
            0xC02 => "instret".to_owned(),
            0x008 => "vstart".to_owned(),
            0xC20 => "vl".to_owned(),
            0xC21 => "vtype".to_owned(),
            0xC22 => "vlenb".to_owned(),
            n => format!("csr_{n:#05x}"),
        }
    }
}

