#[cfg(test)]
mod tests {
    use super::*;

    fn make(mnem: &str, ops: &str) -> Instruction {
        let mut i = Instruction::new(
            rustre_core::address::Address::new(0x8000),
            4,
            mnem,
            vec![],
        );
        i.operands = ops.to_owned();
        i
    }

    #[test]
    fn test_andn() {
        let l = RiscvExtLifter::all();
        let i = make("andn", "t0, t1, t2");
        let r = l.lift(&i).unwrap();
        assert!(matches!(&r.effects[0], Effect::RegWrite { reg, .. } if reg == "t0"));
    }

    #[test]
    fn test_bset() {
        let l = RiscvExtLifter::all();
        let i = make("bset", "a0, a1, a2");
        let r = l.lift(&i).unwrap();
        assert!(!r.effects.is_empty());
    }

    #[test]
    fn test_vsetvli() {
        let l = RiscvExtLifter::all();
        let i = make("vsetvli", "a0, a1, e32,m1");
        let r = l.lift(&i).unwrap();
        // Should produce vl + vtype writes.
        assert!(r.effects.len() >= 2);
    }

    #[test]
    fn test_csrrw() {
        let l = RiscvExtLifter::all();
        let i = make("csrrw", "t0, 0xC00, zero");
        let r = l.lift(&i).unwrap();
        assert_eq!(r.effects.len(), 2);
        match &r.effects[0] {
            Effect::RegWrite { reg, value: IrExpr::Reg(csr) } => {
                assert_eq!(reg, "t0");
                assert!(csr.contains("cycle") || csr.starts_with("csr_"));
            }
            _ => panic!("expected RegWrite"),
        }
    }

    #[test]
    fn test_fence_i() {
        let l = RiscvExtLifter::all();
        let i = make("fence.i", "");
        let r = l.lift(&i).unwrap();
        assert!(matches!(&r.effects[0], Effect::Intrinsic { name, .. } if name == "riscv_fence_i"));
    }

    #[test]
    fn test_vadd_vv() {
        let l = RiscvExtLifter::all();
        let i = make("vadd.vv", "v0, v1, v2");
        let r = l.lift(&i).unwrap();
        assert!(matches!(&r.effects[0], Effect::RegWrite { reg, .. } if reg == "v0"));
    }
}
